file.content:
{
	"$schema": "https://schemas.wp.org/trunk/block.json",
	"apiVersion": 3,
	"name": "telex/block-breadcrumbs-navigation",
	"version": "0.1.0",
	"title": "Breadcrumbs Navigation",
	"category": "theme",
	"icon": "arrow-right-alt2",
	"description": "Display hierarchical navigation breadcrumbs based on post categories",
	"example": {
		"attributes": {
			"showHome": true,
			"separator": "slash",
			"categorySelection": "first"
		}
	},
	"attributes": {
		"showHome": {
			"type": "boolean",
			"default": true
		},
		"separator": {
			"type": "string",
			"default": "slash",
			"enum": ["slash", "chevron", "arrow"]
		},
		"categorySelection": {
			"type": "string",
			"default": "first",
			"enum": ["first", "deepest"]
		}
	},
	"supports": {
		"html": false,
		"align": ["wide", "full"],
		"spacing": {
			"margin": true,
			"padding": true
		},
		"typography": {
			"fontSize": true,
			"lineHeight": true
		},
		"color": {
			"text": true,
			"background": true,
			"link": true
		}
	},
	"textdomain": "breadcrumbs-navigation",
	"editorScript": "file:./index.js",
	"editorStyle": "file:./index.css",
	"style": "file:./style-index.css",
	"render": "file:./render.php"
}

/**
 * Registers a new block provided a unique name and an object defining its behavior.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
import { registerBlockType } from '@wordpress/blocks';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * All files containing `style` keyword are bundled together. The code used
 * gets applied both to the front of your site and to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './style.scss';

/**
 * Internal dependencies
 */
import Edit from './edit';
import metadata from './block.json';

/**
 * Every block starts by registering a new block type definition.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
registerBlockType( metadata.name, {
	/**
	 * @see ./edit.js
	 */
	edit: Edit,
} );

/**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from '@wordpress/i18n';

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { useBlockProps, InspectorControls } from '@wordpress/block-editor';

/**
 * WordPress dependencies
 */
import { PanelBody, ToggleControl, SelectControl, Notice } from '@wordpress/components';
import { useSelect } from '@wordpress/data';
import { useState, useEffect } from '@wordpress/element';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './editor.scss';

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#edit
 *
 * @param {Object}   props               Block props.
 * @param {Object}   props.attributes    Block attributes.
 * @param {Function} props.setAttributes Function to set attributes.
 * @return {Element} Element to render.
 */
export default function Edit( { attributes, setAttributes } ) {
	const { showHome, separator, categorySelection } = attributes;

	const { categories, categoryDetails, allCategories } = useSelect( ( select ) => {
		const coreDataStore = select( 'core' );
		const editorStore = select( 'core/editor' );

		if ( ! coreDataStore || ! editorStore ) {
			return {
				categories: [],
				categoryDetails: [],
				allCategories: [],
			};
		}

		const currentPostId = editorStore.getCurrentPostId();
		const currentPostType = editorStore.getCurrentPostType();

		if ( ! currentPostId || ! currentPostType ) {
			return {
				categories: [],
				categoryDetails: [],
				allCategories: [],
			};
		}

		const post = coreDataStore.getEntityRecord( 'postType', currentPostType, currentPostId );
		const postCategories = post?.categories || [];

		// Fetch all categories to build full hierarchy
		const allCats = coreDataStore.getEntityRecords( 'taxonomy', 'category', {
			per_page: -1,
		} ) || [];

		if ( postCategories.length === 0 ) {
			return {
				categories: [],
				categoryDetails: [],
				allCategories: allCats,
			};
		}

		const details = coreDataStore.getEntityRecords( 'taxonomy', 'category', {
			include: postCategories,
			per_page: -1,
		} );

		return {
			categories: postCategories,
			categoryDetails: details || [],
			allCategories: allCats,
		};
	}, [] );

	const getSeparatorSymbol = () => {
		switch ( separator ) {
			case 'chevron':
				return '›';
			case 'arrow':
				return '→';
			case 'slash':
			default:
				return '/';
		}
	};

	const getAncestors = ( category, allCats ) => {
		const ancestors = [];
		let current = category;

		while ( current.parent ) {
			const parent = allCats.find( cat => cat.id === current.parent );
			if ( parent ) {
				ancestors.push( parent );
				current = parent;
			} else {
				break;
			}
		}

		return ancestors;
	};

	const getAncestorDepth = ( category, allCats ) => {
		return getAncestors( category, allCats ).length;
	};

	const buildCategoryHierarchyInfo = () => {
		if ( ! categoryDetails || categoryDetails.length === 0 ) {
			return null;
		}

		const categoryInfo = categoryDetails.map( cat => {
			const ancestors = getAncestors( cat, allCategories );
			const depth = ancestors.length;
			const hierarchyPath = [...ancestors.reverse().map( a => a.name ), cat.name].join( ' › ' );

			return {
				id: cat.id,
				name: cat.name,
				depth,
				hierarchyPath,
				category: cat,
			};
		} );

		// Sort by depth (deepest first)
		categoryInfo.sort( ( a, b ) => b.depth - a.depth );

		return categoryInfo;
	};

	const buildBreadcrumbPreview = () => {
		const items = [];
		const separatorSymbol = getSeparatorSymbol();

		if ( showHome ) {
			items.push(
				<span key="home" className="breadcrumb-item">
					<a href="#">{ __( 'Home', 'breadcrumbs-navigation' ) }</a>
				</span>
			);
		}

		if ( categoryDetails && categoryDetails.length > 0 ) {
			// Build category hierarchy
			let selectedCategory;

			if ( categorySelection === 'deepest' ) {
				// Find the category with the most ancestors
				selectedCategory = categoryDetails.reduce( ( deepest, cat ) => {
					const depth = cat.parent ? getAncestorDepth( cat, allCategories ) : 0;
					const deepestDepth = deepest ? ( deepest.parent ? getAncestorDepth( deepest, allCategories ) : 0 ) : -1;
					return depth > deepestDepth ? cat : deepest;
				}, null );
			} else {
				// Use first category
				selectedCategory = categoryDetails[0];
			}

			if ( selectedCategory ) {
				const ancestors = getAncestors( selectedCategory, allCategories );

				// Add ancestor categories
				ancestors.reverse().forEach( ( cat ) => {
					items.push(
						<span key={ `sep-${ cat.id }` } className="breadcrumb-separator" aria-hidden="true">
							{ ' ' + separatorSymbol + ' ' }
						</span>
					);
					items.push(
						<span key={ cat.id } className="breadcrumb-item">
							<a href="#">{ cat.name }</a>
						</span>
					);
				} );

				// Add selected category
				items.push(
					<span key={ `sep-${ selectedCategory.id }` } className="breadcrumb-separator" aria-hidden="true">
						{ ' ' + separatorSymbol + ' ' }
					</span>
				);
				items.push(
					<span key={ selectedCategory.id } className="breadcrumb-item">
						<a href="#">{ selectedCategory.name }</a>
					</span>
				);
			}
		}

		// Add current post
		items.push(
			<span key="sep-current" className="breadcrumb-separator" aria-hidden="true">
				{ ' ' + separatorSymbol + ' ' }
			</span>
		);
		items.push(
			<span key="current" className="breadcrumb-item breadcrumb-current">
				{ __( 'Current Post', 'breadcrumbs-navigation' ) }
			</span>
		);

		return items;
	};

	const categoryHierarchyInfo = buildCategoryHierarchyInfo();

	return (
		<>
			<InspectorControls>
				<PanelBody title={ __( 'Breadcrumb Settings', 'breadcrumbs-navigation' ) }>
					<ToggleControl
						label={ __( 'Show Home Link', 'breadcrumbs-navigation' ) }
						help={ __( 'Display "Home" as the first breadcrumb item', 'breadcrumbs-navigation' ) }
						checked={ showHome }
						onChange={ ( value ) => setAttributes( { showHome: value } ) }
					/>
					<SelectControl
						label={ __( 'Separator Style', 'breadcrumbs-navigation' ) }
						value={ separator }
						options={ [
							{ label: __( 'Forward Slash (/)', 'breadcrumbs-navigation' ), value: 'slash' },
							{ label: __( 'Chevron (›)', 'breadcrumbs-navigation' ), value: 'chevron' },
							{ label: __( 'Arrow (→)', 'breadcrumbs-navigation' ), value: 'arrow' },
						] }
						onChange={ ( value ) => setAttributes( { separator: value } ) }
					/>
				</PanelBody>
				<PanelBody title={ __( 'Category Settings', 'breadcrumbs-navigation' ) } initialOpen={ true }>
					<SelectControl
						label={ __( 'Category Selection Strategy', 'breadcrumbs-navigation' ) }
						help={ __( 'Choose which category to display when multiple categories are assigned to a post', 'breadcrumbs-navigation' ) }
						value={ categorySelection }
						options={ [
							{ label: __( 'First Assigned Category', 'breadcrumbs-navigation' ), value: 'first' },
							{ label: __( 'Deepest Category Hierarchy', 'breadcrumbs-navigation' ), value: 'deepest' },
						] }
						onChange={ ( value ) => setAttributes( { categorySelection: value } ) }
					/>

					{ categoryHierarchyInfo && categoryHierarchyInfo.length > 0 && (
						<>
							<div style={{ marginTop: '16px', marginBottom: '8px' }}>
								<strong>{ __( 'Category Hierarchy Analysis', 'breadcrumbs-navigation' ) }</strong>
							</div>
							<Notice status="info" isDismissible={ false }>
								<p style={{ margin: 0, fontSize: '12px' }}>
									{ categorySelection === 'first' 
										? __( 'Using first assigned category', 'breadcrumbs-navigation' )
										: __( 'Using deepest category in hierarchy', 'breadcrumbs-navigation' )
									}
								</p>
							</Notice>
							<div style={{ 
								marginTop: '12px',
								padding: '12px',
								background: '#f7f7f7',
								borderRadius: '4px',
								fontSize: '13px'
							}}>
								{ categoryHierarchyInfo.map( ( info, index ) => (
									<div 
										key={ info.id }
										style={{ 
											marginBottom: index < categoryHierarchyInfo.length - 1 ? '8px' : 0,
											paddingBottom: index < categoryHierarchyInfo.length - 1 ? '8px' : 0,
											borderBottom: index < categoryHierarchyInfo.length - 1 ? '1px solid #ddd' : 'none'
										}}
									>
										<div style={{ fontWeight: '600', marginBottom: '4px' }}>
											{ info.name }
											<span style={{ 
												fontWeight: 'normal',
												color: '#666',
												marginLeft: '8px'
											}}>
												({ __( 'Depth', 'breadcrumbs-navigation' ) }: { info.depth })
											</span>
										</div>
										<div style={{ 
											color: '#666',
											fontSize: '12px',
											fontStyle: 'italic'
										}}>
											{ info.hierarchyPath }
										</div>
									</div>
								) ) }
							</div>
							<p style={{ 
								marginTop: '12px',
								marginBottom: 0,
								fontSize: '12px',
								color: '#666'
							}}>
								{ categorySelection === 'first'
									? __( 'The breadcrumb will use the first category in the list above.', 'breadcrumbs-navigation' )
									: __( 'The breadcrumb will use the category with the greatest depth (most parent categories).', 'breadcrumbs-navigation' )
								}
							</p>
						</>
					) }

					{ ( ! categoryDetails || categoryDetails.length === 0 ) && (
						<Notice status="warning" isDismissible={ false }>
							<p style={{ margin: 0 }}>
								{ __( 'This post has no categories assigned. The breadcrumb will only show Home (if enabled) and the current post.', 'breadcrumbs-navigation' ) }
							</p>
						</Notice>
					) }
				</PanelBody>
			</InspectorControls>
			<nav { ...useBlockProps() } aria-label={ __( 'Breadcrumb', 'breadcrumbs-navigation' ) }>
				<ol className="breadcrumb-list">
					<li>
						{ buildBreadcrumbPreview() }
					</li>
				</ol>
			</nav>
		</>
	);
}

/**
 * The following styles get applied both on the front of your site
 * and in the editor.
 *
 * Replace them with your own styles or remove the file completely.
 */

.wp-block-telex-block-breadcrumbs-navigation {
	font-size: 0.875rem;
	line-height: 1.5;
	padding: 0.75rem 0;

	.breadcrumb-list {
		list-style: none;
		margin: 0;
		padding: 0;
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		gap: 0;
	}

	.breadcrumb-item {
		display: inline-block;

		a {
			color: inherit;
			text-decoration: none;
			transition: opacity 0.2s ease;

			&:hover {
				opacity: 0.7;
				text-decoration: underline;
			}

			&:focus {
				outline: 2px solid currentColor;
				outline-offset: 2px;
				border-radius: 2px;
			}
		}
	}

	.breadcrumb-current {
		color: inherit;
		opacity: 0.7;
	}

	.breadcrumb-separator {
		display: inline-block;
		margin: 0 0.5rem;
		opacity: 0.5;
		user-select: none;
	}

	// Responsive adjustments
	@media (max-width: 600px) {
		font-size: 0.8125rem;

		.breadcrumb-separator {
			margin: 0 0.375rem;
		}
	}
}

/**
 * The following styles get applied inside the editor only.
 *
 * Replace them with your own styles or remove the file completely.
 */

.wp-block-telex-block-breadcrumbs-navigation {
	border: 1px dashed #ccc;
	border-radius: 4px;
	padding: 1rem;
	background-color: #f9f9f9;

	&::before {
		content: "Breadcrumbs Preview";
		display: block;
		font-size: 0.75rem;
		text-transform: uppercase;
		color: #666;
		margin-bottom: 0.5rem;
		font-weight: 600;
		letter-spacing: 0.05em;
	}
}

{
	"name": "breadcrumbs-navigation",
	"version": "0.1.0",
	"description": "A flexible breadcrumbs block that displays hierarchical navigation trails based on post categories with customizable settings and full accessibility support.",
	"author": "WordPress Telex",
	"license": "GPL-2.0-or-later",
	"main": "build/index.js",
	"scripts": {
		"build": "wp-scripts build",
		"format": "wp-scripts format",
		"lint:css": "wp-scripts lint-style",
		"lint:js": "wp-scripts lint-js",
		"packages-update": "wp-scripts packages-update",
		"plugin-zip": "wp-scripts plugin-zip",
		"start": "wp-scripts start"
	},
	"devDependencies": {
		"@wordpress/scripts": "^30.15.0"
	}
}
